import { Ljudmotor } from './delat/ljudmotor.js';
import { META, sidorA, sidorB, uppslagC } from './innehall/natt1.js';

const VARIANT = document.documentElement.dataset.variant || 'A';
const reducerad = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function el(tag, attrs = {}, kids = []) {
  const n = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === 'class') n.className = v;
    else if (k === 'html') n.innerHTML = v;
    else if (k === 'text') n.textContent = v;
    else if (k === 'dataset') Object.assign(n.dataset, v);
    else if (v === false || v == null) continue;
    else n.setAttribute(k, v === true ? '' : v);
  }
  for (const c of kids) if (c) n.append(c);
  return n;
}

function prosa(stycken = []) {
  const box = el('div', { class: 'prosa' });
  for (const s of stycken) box.append(el('p', { text: s }));
  return box;
}

function punkter(lista) {
  if (!lista || !lista.length) return null;
  const ul = el('ul', { class: 'punkter' });
  for (const p of lista) ul.append(el('li', { text: p }));
  return ul;
}

function versblock(vers) {
  const box = el('div', { class: 'vers' });
  box.append(el('p', { class: 'kicker', text: vers.diktare }));
  const mesra = el('div', { class: 'mesra', lang: 'fa' });
  mesra.dir = 'rtl';
  vers.mesra.forEach((rad, i) => {
    if (i) mesra.append(document.createElement('br'));
    mesra.append(document.createTextNode(rad));
  });
  box.append(mesra);
  box.append(el('p', { class: 'tolkning', text: vers.tolkning }));
  box.append(el('p', { class: 'kalla', text: vers.kalla }));
  return box;
}

function textInnehall(data) {
  const frag = document.createDocumentFragment();
  if (data.kicker) frag.append(el('p', { class: 'kicker', text: data.kicker }));
  if (data.rubrik) frag.append(el('h2', { class: 'rubrik', text: data.rubrik }));
  if (data.stycken) frag.append(prosa(data.stycken));
  if (data.punkter) frag.append(punkter(data.punkter));
  if (data.vers) frag.append(versblock(data.vers));
  if (data.fot) frag.append(el('p', { class: 'fotnot', text: data.fot }));
  return frag;
}

function bild(pos) {
  const wrap = el('div', { class: 'bildfalt' });
  const img = el('img', {
    src: META.bild,
    alt: 'Tahmina kommer till Rostam i Samangan om natten.',
  });
  if (pos) img.style.objectPosition = pos;
  wrap.append(img);
  return wrap;
}

function byggSidaA(sida) {
  const root = el('article', { class: 'sida', dataset: { typ: sida.typ } });
  root.append(bild(sida.bildPos));
  const text = el('div', { class: 'textfalt' });
  text.append(textInnehall(sida));
  root.append(text);
  return root;
}

function byggSidaB(sida) {
  const root = el('article', { class: 'sida', dataset: { typ: sida.typ } });
  root.append(bild(sida.bildPos));
  const titel = !sida.stycken && !sida.vers && !sida.punkter && !sida.fot;
  const kort = el('div', { class: 'textkort' + (titel ? ' titel' : '') });
  kort.append(textInnehall(sida));
  root.append(kort);
  return root;
}

function byggBlad(data, sidaKlass) {
  const blad = el('div', { class: 'blad ' + sidaKlass + (data.typ === 'helbild' ? ' helbild' : '') + (data.avslut ? ' avslut' : '') });
  if (data.typ === 'helbild') blad.append(bild(data.bildPos).querySelector('img'));
  else blad.append(textInnehall(data));
  return blad;
}

function byggUppslagC(uppslag) {
  const root = el('article', { class: 'uppslag', dataset: { typ: 'uppslag' } });
  root.append(byggBlad(uppslag.vanster, 'vanster'));
  root.append(byggBlad(uppslag.hoger, 'hoger'));
  return root;
}

function sidlista() {
  if (VARIANT === 'B') return sidorB().map((s) => ({ nod: byggSidaB(s), folio: s.folio, data: s }));
  if (VARIANT === 'C') return uppslagC().map((s) => ({ nod: byggUppslagC(s), folio: s.folio, data: s }));
  return sidorA().map((s) => ({ nod: byggSidaA(s), folio: s.folio, data: s }));
}

function attachFps() {
  let state = null;
  return {
    startFps() {
      state = { t0: performance.now(), last: performance.now(), frames: 0, maxDt: 0 };
      const loop = (now) => {
        if (!state) return;
        const dt = now - state.last;
        state.last = now;
        state.frames += 1;
        if (dt > 0 && dt < 2000) state.maxDt = Math.max(state.maxDt, dt);
        state.raf = requestAnimationFrame(loop);
      };
      state.raf = requestAnimationFrame(loop);
    },
    stopFps() {
      if (!state) return null;
      cancelAnimationFrame(state.raf);
      const ms = performance.now() - state.t0;
      const frames = state.frames;
      const out = {
        frames,
        ms,
        fps: ms > 0 ? (frames * 1000) / ms : 0,
        minFps: state.maxDt ? 1000 / state.maxDt : 0,
      };
      state = null;
      return out;
    },
  };
}

async function startaLjud() {
  const ljud = new Ljudmotor({ storageKey: 'kvarnen-variant-ljud', basUrl: '' });
  ljud.attachUnlock(document);
  ljud.setVolume('master', 0.55, { persist: false });
  ljud.setVolume('sfx', 0.45, { persist: false });
  ljud.setVolume('ambience', 0.2, { persist: false });
  try {
    await ljud.unlock();
    await ljud.loadBank('sida-flip', [
      { ogg: 'data:audio/ogg;base64,', m4a: 'data:audio/mp4;base64,' },
      { ogg: 'data:audio/ogg;base64,', m4a: 'data:audio/mp4;base64,' },
      { ogg: 'data:audio/ogg;base64,', m4a: 'data:audio/mp4;base64,' },
      { ogg: 'data:audio/ogg;base64,', m4a: 'data:audio/mp4;base64,' }
    ]);
  } catch (err) {
    console.warn('Ljudbanken kunde inte laddas', err);
  }
  return ljud;
}

function spelaBlad(ljud) {
  if (!ljud) return;
  ljud.play('sida-flip', { buss: 'sfx', volume: 0.28, pitchJitter: 0.04, volJitter: 1.2 });
}

async function main() {
  const scen = document.querySelector('[data-testid="bok"]');
  const folioEl = document.querySelector('[data-testid="folio"]');
  const btnFore = document.querySelector('[data-testid="fore"]');
  const btnNasta = document.querySelector('[data-testid="nasta"]');
  const lista = sidlista();
  lista.forEach((s) => scen.append(s.nod));

  let index = 0;
  let animerar = false;
  const fps = attachFps();
  let ljud = null;

  function rita(i) {
    lista.forEach((s, n) => {
      s.nod.classList.toggle('synlig', n === i);
      s.nod.classList.remove('ut-vanster', 'ut-hoger', 'in-vanster', 'in-hoger');
    });
    index = i;
    if (folioEl) folioEl.textContent = lista[i].folio;
    if (btnFore) btnFore.disabled = i === 0;
    if (btnNasta) btnNasta.disabled = i === lista.length - 1;
  }

  function vänd(riktning) {
    const nasta = index + riktning;
    if (nasta < 0 || nasta >= lista.length || animerar) return false;
    const fran = lista[index].nod;
    const till = lista[nasta].nod;
    spelaBlad(ljud);
    if (reducerad) {
      rita(nasta);
      return true;
    }
    animerar = true;
    const utKlass = riktning > 0 ? 'ut-hoger' : 'ut-vanster';
    const inKlass = riktning > 0 ? 'in-hoger' : 'in-vanster';
    till.classList.add(inKlass);
    till.classList.add('synlig');
    // force layout so the incoming transform is applied before we clear it
    void till.offsetWidth;
    requestAnimationFrame(() => {
      fran.classList.remove('synlig');
      fran.classList.add(utKlass);
      till.classList.remove(inKlass);
    });
    const klar = () => {
      fran.classList.remove('ut-vanster', 'ut-hoger', 'synlig');
      till.classList.remove('in-vanster', 'in-hoger');
      till.classList.add('synlig');
      index = nasta;
      if (folioEl) folioEl.textContent = lista[index].folio;
      if (btnFore) btnFore.disabled = index === 0;
      if (btnNasta) btnNasta.disabled = index === lista.length - 1;
      animerar = false;
    };
    const t = VARIANT === 'B' ? 500 : VARIANT === 'C' ? 400 : 440;
    setTimeout(klar, t);
    return true;
  }

  function hoppaTill(i) {
    if (i < 0 || i >= lista.length) return;
    rita(i);
  }

  await document.fonts.ready.catch(() => {});
  await Promise.all(
    [...document.images].map((img) => (img.decode ? img.decode() : Promise.resolve()).catch(() => {})),
  );
  rita(0);

  btnFore?.addEventListener('click', () => vänd(-1));
  btnNasta?.addEventListener('click', () => vänd(1));
  document.querySelectorAll('.svepzon.fore').forEach((b) => b.addEventListener('click', () => vänd(-1)));
  document.querySelectorAll('.svepzon.nasta').forEach((b) => b.addEventListener('click', () => vänd(1)));

  document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight' || e.key === ' ') { e.preventDefault(); vänd(1); }
    if (e.key === 'ArrowLeft') { e.preventDefault(); vänd(-1); }
  });

  let pek = null;
  let svepade = false;
  scen.addEventListener('pointerdown', (e) => {
    pek = { x: e.clientX, y: e.clientY, id: e.pointerId };
    svepade = false;
  });
  scen.addEventListener('pointerup', (e) => {
    if (!pek || e.pointerId !== pek.id) return;
    const dx = e.clientX - pek.x;
    const dy = e.clientY - pek.y;
    pek = null;
    if (Math.abs(dx) < 48 || Math.abs(dx) < Math.abs(dy) * 1.2) return;
    svepade = true;
    vänd(dx < 0 ? 1 : -1);
  });
  scen.addEventListener('pointercancel', () => { pek = null; });
  scen.addEventListener('click', (e) => {
    if (svepade) { e.preventDefault(); e.stopPropagation(); svepade = false; }
  }, true);

  const ljudKnapp = document.querySelector('[data-testid="ljud"]');
  let ljudAv = false;
  ljudKnapp?.addEventListener('click', async () => {
    if (!ljud) ljud = await startaLjud();
    ljudAv = !ljudAv;
    ljud.setMuted('sfx', ljudAv);
    ljud.setMuted('master', ljudAv);
    ljudKnapp.textContent = ljudAv ? '♪︎' : '♪';
    ljudKnapp.setAttribute('aria-label', ljudAv ? 'Ljud av' : 'Ljud på');
  });

  // Förbered ljud vid första interaktion, utan att kräva knappen.
  const forsta = async () => {
    document.removeEventListener('pointerdown', forsta);
    if (!ljud) ljud = await startaLjud();
  };
  document.addEventListener('pointerdown', forsta, { once: true });

  window.__variant = {
    namn: VARIANT,
    get index() { return index; },
    get antal() { return lista.length; },
    get animerar() { return animerar; },
    nasta: () => vänd(1),
    fore: () => vänd(-1),
    hoppaTill,
    startFps: fps.startFps,
    stopFps: fps.stopFps,
    redo: true,
  };
}

main().catch((err) => {
  console.error(err);
  const p = document.querySelector('[data-testid="bok"]');
  if (p) p.textContent = 'Varianten kunde inte öppnas.';
});
